/**
 * Hiragana to katakana.
 *
 * The source stores readings in katakana and people type hiragana, so without
 * this 「さっぽろ」 finds nothing while 「サッポロ」 works — which is the wrong way
 * round for a box people type into on a phone.
 */
function katakana(text) {
  return text.replace(/[ぁ-ゖ]/g, (c) => String.fromCharCode(c.charCodeAt(0) + 0x60));
}

/**
 * Places whose name or reading contains `query`.
 *
 * Matches on the municipality, on the prefecture, and on the kana reading, so
 * 「さっぽろ」, 「札幌」 and 「北海道」 all lead somewhere. Ordered by how early the
 * match starts and then by name length, which puts 「札幌市中央区」 above
 * 「北広島市」 for the query 「札幌」.
 */
export function findPlaces(query, limit = 8) {
  const raw = String(query || '').trim();
  if (raw.length === 0) return [];
  const q = raw;
  const qk = katakana(raw);
  const hits = [];
  for (const row of PLACES) {
    const [pref, city, kana] = row;
    const inCity = city.indexOf(q);
    const inKana = kana.indexOf(qk);
    const inPref = pref.indexOf(q);
    if (inCity < 0 && inKana < 0 && inPref < 0) continue;
    const at = inCity >= 0 ? inCity : inKana >= 0 ? inKana + 100 : inPref + 200;
    hits.push({ row, at });
  }
  hits.sort((a, b) => a.at - b.at || a.row[1].length - b.row[1].length);
  return hits.slice(0, limit).map(({ row }) => ({
    pref: row[0], city: row[1], kana: row[2], lon: row[3], lat: row[4],
  }));
}
